void spade_model_run(const float *raw)
{
    spade_normalize(raw, SPADE_INPUT_STEPS, SPADE_INPUT_CHANNELS, level_center, level_scale, (spade_arena + 2048L), spade_mu, spade_sigma);
    spade_conv1d((spade_arena + 2048L), 256L, 4L, (spade_arena + 0L), 8L, w0_kernel, w0_bias, 3L, 1L, 2L);
    spade_batchnorm((spade_arena + 0L), 256L, 8L, (spade_arena + 0L), w1_scale, w1_offset);
    spade_relu((spade_arena + 0L), 2048L, (spade_arena + 0L));
    spade_conv1d((spade_arena + 0L), 256L, 8L, (spade_arena + 2048L), 8L, w3_kernel, w3_bias, 3L, 2L, 4L);
    spade_batchnorm((spade_arena + 2048L), 256L, 8L, (spade_arena + 2048L), w4_scale, w4_offset);
    spade_relu((spade_arena + 2048L), 2048L, (spade_arena + 2048L));
    spade_dense((spade_arena + 4088L), 8L, (spade_arena + 0L), 256L, w7_kernel, w7_bias);
}

const float *spade_model_output(void)
{
    return (spade_arena + 0L);
}

const float *spade_model_mu(void)
{
    return spade_mu;
}

const float *spade_model_sigma(void)
{
    return spade_sigma;
}

int32_t spade_model_decide(void)
{
    return spade_decide((spade_arena + 0L), SPADE_OUTPUT_LEN, 0.000000000e+00f, 0.000000000e+00f);
}
